-- MIZIZI #1247: bounded, versioned question ledger and authorized READ only.
-- Filename generated by accepted Supabase CLI 2.107.0 on isolated GitHub runner.
-- Source: run 39060478412, WK_CLI_MINTED_MIGRATION_PATH=...20261017185928...
-- No authoring RPC, assessment writer, Registry mutation, source grant or sample data.
begin;
set local lock_timeout='5s';
set local statement_timeout='90s';

do $preflight$
begin
 if current_user<>'postgres'
   or to_regclass('mizizi_private.cases') is null
   or to_regclass('mizizi_private.case_receipt_links') is null
   or to_regclass('platform_private.registry_evidence_assertions') is null
   or to_regprocedure('mizizi_private.assert_headquarters_operator_v1(text)') is null
   or to_regprocedure('public.admin_mizizi_cases_v1(integer,timestamptz,uuid)') is null
 then raise exception 'STOP_MZ_QV1_ACCEPTED_BASELINE_ABSENT'; end if;
 if to_regclass('mizizi_private.case_question_versions') is not null
   or to_regprocedure('public.admin_mizizi_case_questions_v1(uuid,integer)') is not null
 then raise exception 'STOP_MZ_QV1_SCHEMA_OR_GATEWAY_COLLISION'; end if;
 if has_schema_privilege('authenticated','mizizi_private','USAGE')
    or has_schema_privilege('service_role','mizizi_private','USAGE')
 then raise exception 'STOP_MZ_QV1_PRIVATE_SCHEMA_EXPOSURE'; end if;
end;
$preflight$;

create table mizizi_private.case_question_versions (
 id uuid primary key default gen_random_uuid(),
 workspace_id uuid not null,
 case_id uuid not null,
 question_id uuid not null,
 question_revision integer not null,
 expected_case_revision integer not null,
 question_text text not null,
 hypotheses jsonb not null,
 question_fingerprint text not null default repeat('0',64),
 frozen_by_user_id uuid not null references auth.users(id)
   on update restrict on delete restrict,
 freeze_reason text not null,
 frozen_at timestamptz not null default clock_timestamp(),
 constraint mz_qv1_case_fk foreign key(workspace_id,case_id)
   references mizizi_private.cases(workspace_id,id)
   on update restrict on delete restrict,
 constraint mz_qv1_unique_revision unique(workspace_id,case_id,question_id,question_revision),
 constraint mz_qv1_expected_revision_positive check(expected_case_revision>=1),
 constraint mz_qv1_question_revision_positive check(question_revision>=1),
 constraint mz_qv1_question_text check(
   char_length(question_text) between 20 and 500
   and question_text=btrim(question_text)
   and question_text !~ '[[:cntrl:]]'
 ),
 constraint mz_qv1_hypotheses_array check(jsonb_typeof(hypotheses)='array'
   and jsonb_array_length(hypotheses) between 2 and 12),
 constraint mz_qv1_reason check(char_length(btrim(freeze_reason)) between 12 and 1000),
 constraint mz_qv1_fingerprint check(question_fingerprint ~ '^[a-f0-9]{64}$')
);
create index mz_qv1_case_latest on mizizi_private.case_question_versions
 (workspace_id,case_id,question_id,question_revision desc);
comment on table mizizi_private.case_question_versions is
 'Append-only competing hypotheses and question revisions; NOT an ACH assessment, Registry decision, independent source-verification record or publication permission.';
alter table mizizi_private.case_question_versions enable row level security;
alter table mizizi_private.case_question_versions force row level security;
revoke all on table mizizi_private.case_question_versions
 from public,anon,authenticated,service_role,mizizi_executor;

-- SQL owns the sequential version and immutable hash. This table has NO
-- authenticated/service/executor INSERT path; future reviewed authoring must
-- verify actual human identity and workspace permissions before insertion.
create function mizizi_private.freeze_case_question_v1()
returns trigger language plpgsql security invoker set search_path=pg_catalog
as $freeze$
declare
 v_case mizizi_private.cases%rowtype;
 v_latest integer;
 h jsonb;
 v_hid text;
 v_hypotheses text[] := array[]::text[];
begin
 select * into v_case from mizizi_private.cases
 where workspace_id=new.workspace_id and id=new.case_id for update;
 if not found then
  raise exception 'Question case not found in workspace' using errcode='42501';
 end if;
 if v_case.revision<>new.expected_case_revision
   or v_case.case_state in ('closed','resolved')
 then raise exception 'Question freeze case revision stale or terminal'
   using errcode='PT409'; end if;
 select max(question_revision) into v_latest
 from mizizi_private.case_question_versions
 where workspace_id=new.workspace_id and case_id=new.case_id
   and question_id=new.question_id;
 if new.question_revision<>coalesce(v_latest,0)+1 then
  raise exception 'Question revision must advance exactly once'
   using errcode='23514';
 end if;
 if jsonb_typeof(new.hypotheses)<>'array'
   or jsonb_array_length(new.hypotheses) not between 2 and 12 then
  raise exception 'Question must have two to twelve hypotheses'
    using errcode='23514';
 end if;
 for h in select value from jsonb_array_elements(new.hypotheses) loop
  if jsonb_typeof(h)<>'object'
   or h-'id'-'label'<>'{}'::jsonb
   or not (h ?& array['id','label'])
   or jsonb_typeof(h->'id')<>'string'
   or jsonb_typeof(h->'label')<>'string'
  then raise exception 'Hypothesis must have only an ID and label'
   using errcode='23514'; end if;
  v_hid:=h->>'id';
  if v_hid !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or char_length(btrim(h->>'label')) not between 3 and 200
    or h->>'label'<>btrim(h->>'label')
    or (h->>'label') ~ '[[:cntrl:]]'
    or v_hid=any(v_hypotheses)
  then raise exception 'Invalid or duplicated hypothesis' using errcode='23514'; end if;
  v_hypotheses:=array_append(v_hypotheses,v_hid);
 end loop;
 new.frozen_at:=clock_timestamp();
 new.question_fingerprint:=encode(extensions.digest(
  concat_ws('|','mizizi-question-v1',new.workspace_id::text,
    new.case_id::text,new.question_id::text,new.question_revision::text,
    new.expected_case_revision::text,new.question_text,new.hypotheses::text,
    new.frozen_by_user_id::text,new.freeze_reason),'sha256'),'hex');
 return new;
end;
$freeze$;
create trigger mz_qv1_freeze_before_insert
 before insert on mizizi_private.case_question_versions
 for each row execute function mizizi_private.freeze_case_question_v1();

create function mizizi_private.block_case_question_change_v1()
returns trigger language plpgsql security invoker set search_path=pg_catalog
as $block$
begin
 raise exception 'MIZIZI frozen question versions are immutable'
 using errcode='23514';
end;
$block$;
create trigger mz_qv1_immutable
 before update or delete on mizizi_private.case_question_versions
 for each row execute function mizizi_private.block_case_question_change_v1();
revoke all on function
 mizizi_private.freeze_case_question_v1(),
 mizizi_private.block_case_question_change_v1()
 from public,anon,authenticated,service_role,mizizi_executor;

-- Authenticated read projection only. Zero source/ACH cells is the TRUE
-- current boundary: neither DB02 review links nor worker hypotheses are
-- independent assessed evidence. Do not join raw Registry source payloads.
create function public.admin_mizizi_case_questions_v1(
 p_case_id uuid,p_expected_case_revision integer
)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog
as $read$
declare
 v_case mizizi_private.cases%rowtype;
 v_count integer;
 v_all integer;
 v_questions jsonb;
begin
 perform mizizi_private.assert_headquarters_operator_v1('reader');
 if p_case_id is null or p_expected_case_revision is null
   or p_expected_case_revision<1 then
  raise exception 'Invalid question read scope' using errcode='22023';
 end if;
 select c.* into v_case
 from mizizi_private.cases c
 join mizizi_private.workspaces w on w.id=c.workspace_id
 where c.id=p_case_id and w.workspace_key='wakilisha-internal'
   and w.workspace_kind='internal' and w.status='active';
 if not found then
  raise exception 'Question case not in authorized workspace'
   using errcode='42501';
 end if;
 if v_case.revision<>p_expected_case_revision then
  raise exception 'Question read stale case revision' using errcode='PT409';
 end if;
 select count(*) into v_all
 from mizizi_private.case_question_versions q
 where q.workspace_id=v_case.workspace_id and q.case_id=v_case.id;
 if v_all=0 then return jsonb_build_object('kind','not_recorded'); end if;

 -- Preserve the distinction between an older frozen question and no
 -- question. A newer case revision needs a separately reviewed re-freeze.
 if exists (
   select 1 from (
      select distinct on (q.question_id)
         q.question_id,q.expected_case_revision
      from mizizi_private.case_question_versions q
      where q.workspace_id=v_case.workspace_id and q.case_id=v_case.id
      order by q.question_id,q.question_revision desc
   ) latest where latest.expected_case_revision<>v_case.revision
 ) then raise exception 'Question sources require a fresh case revision'
   using errcode='PT409'; end if;
 select count(*) into v_count from (
  select distinct question_id from mizizi_private.case_question_versions
  where workspace_id=v_case.workspace_id and case_id=v_case.id
 ) questions;
 if v_count>100 then
  raise exception 'Question read exceeds bounded page size' using errcode='54000'; end if;

 select coalesce(jsonb_agg(jsonb_build_object(
   'questionId',latest.question_id,
   'questionRevision',latest.question_revision,
   'caseId',v_case.id,'caseRevision',v_case.revision,
   'question',latest.question_text,
   'hypotheses',latest.hypotheses,
   'sources','[]'::jsonb,
   'assessments','[]'::jsonb
 ) order by latest.question_id),'[]'::jsonb) into v_questions
 from (
    select distinct on (q.question_id)
      q.question_id,q.question_revision,q.question_text,q.hypotheses
    from mizizi_private.case_question_versions q
    where q.workspace_id=v_case.workspace_id and q.case_id=v_case.id
    order by q.question_id,q.question_revision desc
 ) latest;
 return jsonb_build_object(
   'kind','ready','contract','mizizi.question_read.v1',
   'workspaceId',v_case.workspace_id,'caseId',v_case.id,
   'caseRevision',v_case.revision,'questions',v_questions);
end;
$read$;
revoke all on function public.admin_mizizi_case_questions_v1(uuid,integer)
 from public,anon,authenticated,service_role,mizizi_executor;
grant execute on function public.admin_mizizi_case_questions_v1(uuid,integer)
 to authenticated;

commit;
